## ReproOS-Campaign-Completion M6 deliverable 5: a hermetic multi-repository
## fixture that uses only published commits and generated interface
## artifacts (``federated_catalog_fixture``; what "published" means for a
## hermetic test is stated in that module's docstring).
##
## This test proves the fixture's properties rather than the consumer's
## refusals (those are the federated e2e and the M6 deliverable 4 test):
##
##   * the artifacts are GENERATED by each catalog's own provider through the
##     production publisher -- the provider leaves evidence that it was
##     compiled and run when publishing, and the published record is the one
##     its source declares;
##   * two constructions of the same world in two different roots, each
##     extracting afresh (the publisher memo bypassed), give byte-identical
##     artifacts, commit ids, root trees, interface-artifact identities and
##     lock selections, and no artifact byte names either root;
##   * a consumer reads COMMITTED objects only: a catalog working tree (and
##     index) that differs from its commit changes nothing -- and the same
##     change, once committed and synced, does change the selection (the
##     control);
##   * develop overrides naming the catalogs change nothing;
##   * ambient git configuration and ``GIT_*`` variables reach neither the
##     fixture's commits nor discovery -- and the same poison configuration,
##     outside the hermetic environment, would have changed discovery's
##     answer (the control);
##   * a consumer resolves interfaces and contributions from the pinned
##     catalogs with no develop override anywhere, and no catalog provider
##     is compiled or run while it does.
##
## Built and run on Windows only in this round (WSL down).

import std/[os, osproc, sequtils, strutils, tempfiles, unittest]

import repro_interface_artifacts
import repro_interface_artifacts/catalog_composition
import repro_interface_artifacts/contribution_fingerprint
import repro_cli_support
import repro_lock
import repro_project_dsl

import ./federated_catalog_fixture

package federatedTool:
  executable federatedTool:
    name "federated-tool"
    cli:
      subcmd "run":
        flag verbose, bool

package federatedConsumer:
  defaultToolProvisioning "tarball"
  uses:
    "federatedTool"

let Host = currentPlatformId()

proc findPackage(name: string): PackageDef =
  for pkg in registeredPackages():
    if pkg.packageName == name:
      return pkg
  raise newException(ValueError, "package not registered: " & name)

proc consumerDef(contributor: string; archive: FixtureArchive;
                 toolFingerprint: string): ProvisioningContributionDef =
  ## What the consumer imports for a catalog's contribution: the same
  ## record the catalog published (checked by record digest below).
  ProvisioningContributionDef(targetPackage: FedToolPackage,
    targetInterfaceFingerprint: toolFingerprint, contributor: contributor,
    tarballProvisioning: @[TarballProvisioningDef(url: archive.url,
      sha256: archive.sha256, archiveType: "tar.gz",
      executablePath: fixtureExecutableRelPath(FedToolExecutable),
      stripComponents: 1, packageId: FedToolPackageId,
      lockIdentity: "sha256:" & archive.sha256)],
    sourceFile: "catalogs/" & contributor.split('/')[^1] & "/repro.nim",
    sourceLine: 3)

proc consumerArtifact(defs: seq[ProvisioningContributionDef];
                      consumerRoot: string): ProjectInterfaceArtifact =
  var pi = toProjectInterface(findPackage("federatedConsumer"),
    registeredPackages(), defs)
  markImportedContributions(pi, consumerRoot / "repro.nim")
  artifactFor(pi)

proc baseLockText(): string =
  serializeLockedDependencies(LockedDependencies(
    schema: SolvedGraphLockSchemaV2, platform: Host, optimal: true,
    inputsDigest: inputsDigestOf("federated-fixture"),
    packages: @[LockedPackage(name: "nim", version: "2.2.8", source: "nim",
      selection: ssSelected)]))

proc newConsumer(at: string; imports: seq[ImportSpec];
                 policy = @[(FedToolPackage, FedContributorA)]): string =
  result = at
  createDir(result)
  writeFile(result / "repro.solver", "package app\nversions: 1.0.0\n")
  writeFile(result / "repro.lock", baseLockText())
  writeDeclaration(result, imports, policy)

proc refresh(dir: string): int =
  runReproLockCommand(@["refresh", dir, "--inputs", dir / "repro.solver",
    "--provisioning"])

proc lockLine(text, key: string): string =
  for line in text.splitLines():
    if line.startsWith(key & " = "):
      return line

proc selection(dir: string): string =
  ## What the consumer's lock SELECTS: its catalog pins and provisioning
  ## records (the rest of a refreshed lock names the project directory).
  let text = readFile(dir / "repro.lock")
  lockLine(text, CatalogImportsLockKey) & "\n" &
    lockLine(text, ProvisioningLockKey)

proc comparable(s: string): string =
  result = s.replace('\\', '/')
  when defined(windows):
    result = result.toLowerAscii()

proc bytesOf(files: seq[PublishedArtifactFile]): seq[string] =
  files.mapIt(it.fileName & "\n" & it.bytes)

suite "hermetic published catalog fixture":
  when defined(windows):
    putEnv("PATH", getEnv("SystemRoot", r"C:\Windows") / "System32" & ";" &
      getEnv("PATH"))
  putEnv("REPRO_CACHE_DISABLE", "1")
  let top = createTempDir("repro-fixture-", "")
  let shared = top / "shared"         # identical inputs for both roots
  createDir(shared)
  let archiveA = buildFixtureArchive(shared, "a1", "fixture-tool-from-a",
    FedToolTopDir, FedToolExecutable)
  let archiveB = buildFixtureArchive(shared, "b1", "fixture-tool-from-b",
    FedToolTopDir, FedToolExecutable)
  let compiledMarker = shared / "provider-compiled.marker"
  let ranMarker = shared / "provider-ran.marker"
  let prelude = providerMarkerPrelude(compiledMarker, ranMarker)
  let root1 = top / "r1"
  let root2 = top / "second-root" / "r2"

  proc publishScratch(): seq[string] =
    for kind, path in walkDir(getTempDir()):
      if kind == pcDir and
          path.extractFilename.startsWith("repro-catalog-publish-" &
            $getCurrentProcessId() & "-"):
        result.add(path)
  let scratchBefore = publishScratch()

  # Construction 1, extracting afresh.
  var env1 = enterHermeticEnvironment(root1)
  let before = extractionCount
  let w1 = newStandardWorld(root1, "fx", archiveA, archiveB, env1.clonesRoot,
    memo = false, preludeA = prelude)
  let extracted1 = extractionCount - before
  let markersAfterPublishing = fileExists(compiledMarker) and
    fileExists(ranMarker)
  env1.leave()

  # Construction 2: another root, another HOME, another clone store.
  if fileExists(compiledMarker): removeFile(compiledMarker)
  if fileExists(ranMarker): removeFile(ranMarker)
  var env2 = enterHermeticEnvironment(root2)
  let w2 = newStandardWorld(root2, "fx", archiveA, archiveB, env2.clonesRoot,
    memo = false, preludeA = prelude)
  let extracted2 = extractionCount - before - extracted1
  let consumer2 = newConsumer(root2 / "consumer", w2.standardImports())
  let refreshed2 = refresh(consumer2)
  let selection2 = selection(consumer2)
  env2.leave()

  let leftoverScratch = publishScratch().filterIt(it notin scratchBefore)
  env1 = enterHermeticEnvironment(root1)

  test "each catalog's provider generated its artifacts through the production publisher":
    # Every publication was a real extraction (3 per construction).
    check extracted1 == 3
    check extracted2 == 3
    # Publishing compiled AND ran catalog A's provider (its prelude left both
    # markers): the artifact is the provider's output, not hand-written.
    check markersAfterPublishing
    # The published records are what the providers declare.
    let recordA = recordOfPublished(w1.publishedA1)
    check recordA.contributor == FedContributorA
    check recordA.targetInterfaceFingerprint == w1.toolFingerprint
    check recordA.tarballProvisioning.len == 1
    check recordA.tarballProvisioning[0].url == archiveA.url
    check recordA.tarballProvisioning[0].sha256 == archiveA.sha256
    check not recordA.imported
    check not recordA.developInterface
    # ... and identical, by record digest, to what the consumer imports.
    check interfaceContributionRecordDigest(recordA) ==
      interfaceContributionRecordDigest(toProjectInterface(
        findPackage("federatedConsumer"), registeredPackages(),
        @[consumerDef(FedContributorA, archiveA, w1.toolFingerprint)]).
        provisioningContributions[0])
    # The canonical interface the interface catalog published is the one
    # this process computes for the same package definition.
    check w1.toolFingerprint == canonicalPackageInterfaceFingerprint(
      findPackage(FedToolPackage), registeredPackages())
    # Locations are repository-relative: the canonical package and the
    # contribution are declared in the catalog's own ``repro.nim``.
    check w1.publishedPackages[0].artifact.projectInterface.location.file ==
      "repro.nim"
    check recordA.location.file == "repro.nim"
    # The commit carries the provider source and the generated artifacts.
    let bareA = sharedCloneOf(env1.clonesRoot, w1.a.remote)
    check git(["--git-dir=" & bareA, "show", w1.revA1 & ":repro.nim"]).
      contains(FedContributorA)
    check git(["--git-dir=" & bareA, "cat-file", "-t",
      w1.revA1 & ":published-interfaces/fedCatalogA.rbsz"]).strip() == "blob"

  test "two constructions in two roots publish byte-identical artifacts, commits and identities":
    check bytesOf(w1.publishedPackages) == bytesOf(w2.publishedPackages)
    check bytesOf(w1.publishedA1) == bytesOf(w2.publishedA1)
    check bytesOf(w1.publishedB1) == bytesOf(w2.publishedB1)
    # A commit id binds the whole tree -- provider source and artifacts --
    # and the fixed identity and date: equal ids are equal publications.
    check w1.revPackages == w2.revPackages
    check w1.revA1 == w2.revA1
    check w1.revB1 == w2.revB1
    check w1.toolFingerprint == w2.toolFingerprint
    for (repo1, repo2, rev) in [(w1.packages, w2.packages, w1.revPackages),
                                (w1.a, w2.a, w1.revA1), (w1.b, w2.b, w1.revB1)]:
      check rootTreeOf(sharedCloneOf(env1.clonesRoot, repo1.remote), rev) ==
        rootTreeOf(sharedCloneOf(root2 / "clones", repo2.remote), rev)
    for files in [w1.publishedPackages, w1.publishedA1, w1.publishedB1]:
      check catalogArtifactIdentity(files.mapIt(it.artifact)).len == 64
      for f in files:
        # No artifact byte names either root, the shared inputs' directory
        # aside (the archive URL is an input both providers declare).
        check comparable(root1) notin comparable(f.bytes)
        check comparable(root2) notin comparable(f.bytes)
        check comparable(FixtureReproRoot) notin comparable(f.bytes)
    # The consumer's lock selects the same pins and records from either.
    let consumer1 = newConsumer(root1 / "consumer", w1.standardImports())
    check refresh(consumer1) == 0
    check refreshed2 == 0
    check selection(consumer1) == selection2
    check selection2.len > 200
    let pins = parseLockedDependencies(readFile(consumer1 / "repro.lock")).
      lockedCatalogImportPins()
    check pins.mapIt(it.repo) == @[FedRepoA, FedRepoB, FedRepoPackages]
    check pins.filterIt(it.repo == FedRepoA)[0].interfaceArtifact ==
      catalogArtifactIdentity(w1.publishedA1.mapIt(it.artifact))
    check pins.filterIt(it.repo == FedRepoPackages)[0].interfaceArtifact ==
      catalogArtifactIdentity(w1.publishedPackages.mapIt(it.artifact))

  test "a consumer resolves from the pinned catalogs with no develop override, compiling and running no provider":
    if fileExists(compiledMarker): removeFile(compiledMarker)
    if fileExists(ranMarker): removeFile(ranMarker)
    let dir = newConsumer(root1 / "consumer-resolve", w1.standardImports())
    check not fileExists(dir / ".repro" / "develop-overrides.toml")
    check refresh(dir) == 0
    let records = parseLockedDependencies(readFile(dir / "repro.lock")).
      lockedProvisioningClaims()
    check records.len == 1
    check records[0].contributor == FedContributorA
    check records[0].interfaceFingerprint == w1.toolFingerprint
    check records[0].catalogRevision == w1.revA1
    let defs = @[consumerDef(FedContributorA, archiveA, w1.toolFingerprint),
      consumerDef(FedContributorB, archiveB, w1.toolFingerprint)]
    let pins = buildProvisioningPins(consumerArtifact(defs, dir), dir)
    check pins.len == 1
    check pins[0].contributor == FedContributorA
    check pins[0].contributionRecordDigest ==
      interfaceContributionRecordDigest(recordOfPublished(w1.publishedA1))
    check not fileExists(compiledMarker)
    check not fileExists(ranMarker)

  test "a working tree that differs from the commit changes nothing; committing it does":
    let defs = @[consumerDef(FedContributorA, archiveA, w1.toolFingerprint),
      consumerDef(FedContributorB, archiveB, w1.toolFingerprint)]
    let baseline = newConsumer(root1 / "consumer-wt-base", w1.standardImports())
    check refresh(baseline) == 0
    let baseSelection = selection(baseline)
    let basePins = buildProvisioningPins(consumerArtifact(defs, baseline),
      baseline)
    # Catalog A's working tree now declares B's archive and carries B's
    # GENERATED artifact under A's file name, plus a stray file -- in the
    # working tree, and staged in the index.
    let upstreamA = w1.a.upstream
    writeFile(upstreamA / "repro.nim", fedCatalogSource("fedCatalogA",
      [fedContribution(FedContributorA, archiveB, w1.toolFingerprint)]))
    writeFile(upstreamA / "published-interfaces" / "fedCatalogA.rbsz",
      w1.publishedB1[0].bytes)
    writeFile(upstreamA / "published-interfaces" / "stray.rbsz", "dirty")
    discard git(["add", "-A"], upstreamA)
    let stagedBlob = git(["hash-object",
      upstreamA / "published-interfaces" / "fedCatalogA.rbsz"]).strip()
    # The shared clone is synced again: a fetch transfers commits only.
    let bareA = w1.a.syncSharedClone(env1.clonesRoot)
    check execCmdEx("git --git-dir=" & quoteShell(bareA) & " cat-file -e " &
      stagedBlob).exitCode != 0
    let dirty = newConsumer(root1 / "consumer-wt-dirty", w1.standardImports())
    check refresh(dirty) == 0
    check selection(dirty) == baseSelection
    check buildProvisioningPins(consumerArtifact(defs, dirty), dirty) ==
      basePins
    check buildProvisioningPins(consumerArtifact(defs, baseline), baseline) ==
      basePins
    # The control: a change that IS committed and synced -- one file next
    # to the provider, the generated artifacts untouched -- moves A's pin
    # (a new revision, and a new provider identity, since that binds the
    # whole tree), so the unchanged result above is not vacuous.
    discard git(["reset", "-q", "--hard"], upstreamA)
    discard git(["clean", "-q", "-f", "-d"], upstreamA)
    writeFile(upstreamA / "NOTES.md", "committed change\n")
    discard git(["add", "-A"], upstreamA)
    discard git(["commit", "-q", "-m", "a committed change"], upstreamA)
    let moved = (revision: git(["rev-parse", "HEAD"], upstreamA).strip())
    discard w1.a.syncSharedClone(env1.clonesRoot)
    let after = newConsumer(root1 / "consumer-wt-after", w1.standardImports())
    check refresh(after) == 0
    check selection(after) != baseSelection
    let pinsAfter = parseLockedDependencies(readFile(after / "repro.lock")).
      lockedCatalogImportPins()
    check pinsAfter.filterIt(it.repo == FedRepoA)[0].revision ==
      moved.revision
    # The baseline consumer's lock still pins the old revision and builds
    # exactly as before.
    check buildProvisioningPins(consumerArtifact(defs, baseline), baseline) ==
      basePins

  test "develop overrides naming the catalogs change nothing":
    let defs = @[consumerDef(FedContributorA, archiveA, w1.toolFingerprint),
      consumerDef(FedContributorB, archiveB, w1.toolFingerprint)]
    let ws = root1 / "override-ws"
    let baseline = newConsumer(ws / "base", w1.standardImports())
    writeFile(baseline / "repro.lock", baseLockText())
    # Pin the original revisions so the earlier test's republication of A
    # does not enter: B by commit, A and the interfaces by commit too.
    var specs = w1.standardImports()
    specs[0] = ImportSpec(repo: FedRepoPackages, remote: w1.packages.remote,
      commit: w1.revPackages)
    specs[1] = ImportSpec(repo: FedRepoA, remote: w1.a.remote,
      commit: w1.revA1)
    writeDeclaration(baseline, specs, @[(FedToolPackage, FedContributorA)])
    check refresh(baseline) == 0
    let baseSelection = selection(baseline)
    let basePins = buildProvisioningPins(consumerArtifact(defs, baseline),
      baseline)
    # A checkout of each catalog next to the consumer, made dirty, and a
    # develop override for every catalog repo name pointing at it -- in
    # the workspace's override file and through the engine's variable.
    var overrides = "schema = \"reprobuild.workspace.develop-overrides.v1\"\n"
    var json = "{\"overrides\": {"
    var first = true
    for repo in [w1.packages, w1.a, w1.b]:
      let checkout = ws / repo.name
      discard git(["clone", "-q", repo.upstream, checkout])
      writeFile(checkout / "published-interfaces" / "x.rbsz", "dirty")
      writeFile(checkout / "repro.nim", "{.error: \"never compiled\".}\n")
      overrides.add("\n[[override]]\npackage = \"" & repo.name &
        "\"\nlocal_path = \"" & checkout.replace('\\', '/') &
        "\"\nstate = \"editable\"\ncreated_at = \"2026-10-01T00:00:00Z\"\n")
      json.add((if first: "" else: ", ") & "\"" & repo.name & "\": \"" &
        checkout.replace('\\', '/') & "\"")
      first = false
    json.add("}}")
    for at in [ws, baseline]:
      createDir(at / ".repro")
      writeFile(at / ".repro" / "develop-overrides.toml", overrides)
    writeFile(ws / "overrides.json", json)
    putEnv("REPRO_DEVELOP_OVERRIDES_FILE", ws / "overrides.json")
    try:
      let dir = newConsumer(ws / "with-overrides", specs)
      createDir(dir / ".repro")
      writeFile(dir / ".repro" / "develop-overrides.toml", overrides)
      check refresh(dir) == 0
      check selection(dir) == baseSelection
      check buildProvisioningPins(consumerArtifact(defs, dir), dir) == basePins
      check buildProvisioningPins(consumerArtifact(defs, baseline),
        baseline) == basePins
    finally:
      delEnv("REPRO_DEVELOP_OVERRIDES_FILE")

  test "the publisher refuses what a consumer would refuse, and host paths":
    let catalogRoot = w1.a.upstream
    let extracted = recordOfPublished(w1.publishedA1)
    proc refusal(artifact: ProjectInterfaceArtifact;
                 hostPaths: seq[string] = @[]): string =
      try:
        discard publishableArtifact(artifact, catalogRoot, "repro.nim",
          hostPaths)
        ""
      except CatalogPublicationError as err:
        err.msg
    let good = w1.publishedA1[0].artifact
    check refusal(good) == ""
    # A location outside the catalog repository: it could only publish a
    # host path.
    var outside = good
    outside.projectInterface.provisioningContributions[0].location.file =
      root2 / "elsewhere.nim"
    check refusal(outside) == "catalog " & catalogRoot &
      " cannot publish repro.nim:\n  source locations outside the catalog " &
      "repository " & catalogRoot & " would publish a host path: " &
      root2 / "elsewhere.nim" & ":" & $extracted.location.line
    # An absolute location INSIDE it is made relative.
    var inside = good
    inside.projectInterface.provisioningContributions[0].location.file =
      catalogRoot / "sub" / "x.nim"
    let insidePublished = publishableArtifact(inside, catalogRoot, "repro.nim")
    check insidePublished.artifact.projectInterface.
      provisioningContributions[0].location.file == "sub/x.nim"
    check insidePublished.artifact.interfaceFingerprint ==
      good.interfaceFingerprint
    # A record a consumer refuses is not published.
    var develop = good
    develop.projectInterface.provisioningContributions[0].developInterface =
      true
    check refusal(develop) == "catalog " & catalogRoot &
      " cannot publish repro.nim:\n  published artifact " &
      "published-interfaces/fedCatalogA.rbsz: contribution from \"" &
      FedContributorA & "\" for package \"" & FedToolPackage &
      "\" uses developInterface, which is forbidden in a published " &
      "catalog snapshot"
    # A host path anywhere in the bytes (here: the catalog root inside an
    # archive URL).
    var leaky = good
    leaky.projectInterface.provisioningContributions[0].
      tarballProvisioning[0].url = "file:///" & catalogRoot.replace('\\', '/') &
        "/x.tar.gz"
    check refusal(leaky) == "catalog " & catalogRoot &
      " cannot publish repro.nim:\n  the encoded artifact contains the host " &
      "path " & catalogRoot
    # ... and any further host path the caller names (here the directory
    # of the archives the provider declares).
    check refusal(good, @[shared]) == "catalog " & catalogRoot &
      " cannot publish repro.nim:\n  the encoded artifact contains the host " &
      "path " & shared
    # A project name that cannot name a file.
    var named = good
    named.projectInterface.projectName = "a/b"
    check "project name \"a/b\" contains \"/\"" in refusal(named)
    # Two modules publishing one file, and a publication of nothing.
    let file = publishableArtifact(good, catalogRoot, "repro.nim")
    let scratch = top / "publish-scratch"
    createDir(scratch)
    for (files, expected) in [(@[file, file], "two modules publish " &
                                 "fedCatalogA.rbsz"),
                              (newSeq[PublishedArtifactFile](),
                                 "publishes nothing")]:
      var raised = ""
      try:
        writePublishedInterfaces(scratch, files)
      except CatalogPublicationError as err:
        raised = err.msg
      check expected in raised
      check not dirExists(scratch / "published-interfaces")
    var missing = ""
    try:
      discard extractCatalogModule(catalogRoot, "absent.nim",
        FixtureReproRoot, scratch / "x")
    except CatalogPublicationError as err:
      missing = err.msg
    check missing == "catalog " & catalogRoot &
      " has no provider module absent.nim"
    # The archives a provider declares are reproducible too: built again in
    # another directory, the same bytes.
    let again = buildFixtureArchive(top / "archives-again", "a1",
      "fixture-tool-from-a", FedToolTopDir, FedToolExecutable)
    check again.sha256 == archiveA.sha256
    # The publisher left no scratch directory behind.
    check leftoverScratch.len == 0

  test "ambient git configuration and GIT_* variables reach neither the fixture nor discovery":
    env1.leave()
    # A poisoned ambient environment: a global configuration that rewrites
    # the catalogs' remote host, signs commits, runs hooks, renames the
    # author; and repository variables pointed elsewhere.
    let poison = top / "poison-home"
    createDir(poison / "hooks")
    let hookMarker = poison / "hook-ran.marker"
    writeFile(poison / "hooks" / "post-commit",
      "#!/bin/sh\necho ran > '" & hookMarker.replace('\\', '/') & "'\n")
    writeFile(poison / ".gitconfig",
      "[url \"https://evil.invalid/\"]\n\tinsteadOf = https://example.invalid/\n" &
      "[commit]\n\tgpgsign = true\n[core]\n\thooksPath = " &
      (poison / "hooks").replace('\\', '/') & "\n[user]\n\tname = Poison\n" &
      "\temail = poison@example.invalid\n")
    var saved: seq[(string, string, bool)] = @[]
    for (k, v) in [("HOME", poison), ("XDG_CONFIG_HOME", poison),
                   ("GIT_CONFIG_GLOBAL", poison / ".gitconfig"),
                   ("GIT_AUTHOR_NAME", "Poison"),
                   ("GIT_DIR", poison / "nowhere.git")]:
      saved.add((k, getEnv(k), existsEnv(k)))
      putEnv(k, v)
    try:
      # The control: under this environment discovery's answer changes --
      # the shared clone now "fetches from" the rewritten host and refuses.
      putEnv("REPRO_WORKSPACE_CLONES", env1.clonesRoot)
      let probe = newConsumer(top / "poison-probe", w1.standardImports())
      let probeText = readFile(probe / "repro.lock")
      let refused = reselectCommittedProvisioning(probe, probe / "repro.lock",
        true, probeText, probeText, Host, Host)
      check not refused.reselected
      check "fetches (after url.*.insteadOf) from https://evil.invalid/" in
        refused.refusals.join("\n")
      # Inside the hermetic environment the same world is built and read
      # exactly as with no ambient configuration at all.
      let root3 = top / "r3"
      var env3 = enterHermeticEnvironment(root3)
      try:
        # The poisoned variables are gone inside the environment, and the
        # isolated HOME is in place.
        for (k, _) in [("GIT_CONFIG_GLOBAL", ""), ("GIT_AUTHOR_NAME", ""),
                       ("GIT_DIR", "")]:
          check not existsEnv(k)
        check getEnv("HOME") == root3 / "home"
        let w3 = newStandardWorld(root3, "fx", archiveA, archiveB,
          env3.clonesRoot, preludeA = prelude)
        check w3.revPackages == w1.revPackages
        check w3.revA1 == w1.revA1
        check w3.revB1 == w1.revB1
        let dir = newConsumer(root3 / "consumer", w3.standardImports())
        check refresh(dir) == 0
        check selection(dir) == selection2
        check not fileExists(hookMarker)
        check git(["--git-dir=" & sharedCloneOf(env3.clonesRoot, w3.a.remote),
          "log", "-1", "--format=%an <%ae>", w3.revA1]).strip() ==
          "Catalog Publisher <publisher@example.invalid>"
      finally:
        env3.leave()
    finally:
      for (k, v, existed) in saved:
        if existed: putEnv(k, v) else: delEnv(k)
      env1 = enterHermeticEnvironment(root1)

  env1.leave()
  removeDir(top)
